import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TextSense: ML Que Se Despliega Como un Servicio Real","description":"Por qué la mayoría de repos de NLP son notebooks — y cómo TextSense envuelve un transformer en el andamiaje operativo que un servicio real necesita.","frontmatter":{"title":"TextSense: ML Que Se Despliega Como un Servicio Real","description":"Por qué la mayoría de repos de NLP son notebooks — y cómo TextSense envuelve un transformer en el andamiaje operativo que un servicio real necesita."},"headers":[],"relativePath":"es/vibe-stories/story-3/index.md","filePath":"es/vibe-stories/story-3/index.md"}`),a={name:`es/vibe-stories/story-3/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="textsense-ml-que-se-despliega-como-un-servicio-real" tabindex="-1">TextSense: ML Que Se Despliega Como un Servicio Real <a class="header-anchor" href="#textsense-ml-que-se-despliega-como-un-servicio-real" aria-label="Permalink to “TextSense: ML Que Se Despliega Como un Servicio Real”">​</a></h1><p>La mayoría de los repos de &quot;NLP API&quot; son un notebook detrás de un Flask <code>if __name__ == &quot;__main__&quot;</code>. Mueren en cuanto alguien hace una pregunta de producción: ¿dónde están las métricas? ¿qué pasa si el modelo no carga? ¿cómo escalas? <strong><a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">TextSense</a></strong> es mi respuesta — un modelo de ML envuelto en el andamiaje operativo que un servicio real necesita.</p><h2 id="la-apuesta-de-ingenieria" tabindex="-1">La apuesta de ingeniería <a class="header-anchor" href="#la-apuesta-de-ingenieria" aria-label="Permalink to “La apuesta de ingeniería”">​</a></h2><p>Análisis de sentimiento e intención sobre HTTP, con backend transformer (DistilBERT SST-2). Eso es lo básico. La apuesta estaba en todo lo que rodea al modelo:</p><ul><li><strong>Degradación elegante</strong> — un patrón <code>ModelProvider</code> prueba <code>transformers</code> primero; si los pesos no están disponibles, un motor léxico determinista responde con el <em>mismo contrato de API</em>. El servicio nunca falla en seco porque un modelo no se descargó.</li><li><strong>Disciplina de latencia</strong> — inferencia de calentamiento al arrancar, un endpoint batch con micro-batching interno, y caché para que las entradas repetidas no se recalculen.</li><li><strong>Observabilidad desde el día uno</strong> — <code>/metrics</code> en formato Prometheus con contadores de peticiones, histogramas de latencia, aciertos de caché y el backend de modelo activo como etiqueta.</li></ul><h2 id="respuestas-honestas" tabindex="-1">Respuestas honestas <a class="header-anchor" href="#respuestas-honestas" aria-label="Permalink to “Respuestas honestas”">​</a></h2><p>Cada respuesta lleva el id del modelo que la produjo — <code>distilbert-sst2</code> o <code>lexicon-v1</code> — porque un score sin procedencia es una suposición que finge ser dato. Autenticación opcional por API-key, límites de tamaño de payload y sanitización de entrada completan la superficie.</p><h2 id="lo-que-demuestra" tabindex="-1">Lo que demuestra <a class="header-anchor" href="#lo-que-demuestra" aria-label="Permalink to “Lo que demuestra”">​</a></h2><p>Los 15+ tests de pytest corren offline en menos de cinco segundos contra el backend léxico — sin GPU, sin gigas de descargas, CI en verde en cada push. TextSense es el raro repo de ML escrito desde la silla de un ingeniero de backend: la elección del modelo importa menos que el contrato, las métricas y la historia de fallos. Esa es la mentalidad que aporto a cualquier equipo cercano a la IA — el modelo es un componente, el servicio es el producto.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};